import { writeFileSync, mkdirSync } from 'node:fs';
import { buildMatrix } from '../src/lib/coverageMatrix.ts';
import { LESSONS } from '../src/data/lessons.ts';
import { QUESTIONS } from '../src/data/questions.ts';
import { MIN_QUESTIONS } from '../src/data/curriculumPlan.ts';

const rows = buildMatrix();
const n = (s: string) => rows.filter((r) => r.status === s).length;
const out = [
  '# Coverage matrix (generated by `npm run coverage`: do not edit by hand)', '',
  `Lessons: ${LESSONS.length} · Questions: ${QUESTIONS.length} · Covered: ${n('covered')} · Partial: ${n('partial')} · Gap: ${n('gap')} · Thin (covered but few questions or levels): ${rows.filter((r) => r.depth === 'thin').length}`, '',
  `"Covered" = at least 1 lesson (or object page) and at least ${MIN_QUESTIONS} questions. Object pages are still brief and unverified unless marked checked.`, '',
  '| Item | Lessons | Questions | Status | Depth | Planned batch |', '|---|---|---|---|---|---|',
  ...rows.map((r) => `| ${r.label} | ${r.lessons.join(', ') || '-'} | ${r.questions.length} | ${r.status.toUpperCase()} | ${r.depth} | ${r.plan ?? '?'} |`), '',
];
mkdirSync('docs', { recursive: true });
writeFileSync('docs/COVERAGE.md', out.join('\n'));
console.log(out.slice(2, 3).join(''));
